ALTER TABLE detalle_compra ENABLE TRIGGER USER;
ALTER TABLE detalle_venta ENABLE TRIGGER USER;
ALTER TABLE venta ENABLE TRIGGER USER;
ALTER TABLE abonos ENABLE TRIGGER USER;
ALTER TABLE record_crediticio ENABLE TRIGGER USER;
ALTER TABLE productos_devueltos ENABLE TRIGGER USER;
SELECT setval(pg_get_serial_sequence('persona','id_persona'), COALESCE((SELECT MAX(id_persona) FROM persona),1));
SELECT setval(pg_get_serial_sequence('productos','id_producto'), COALESCE((SELECT MAX(id_producto) FROM productos),1));
SELECT setval(pg_get_serial_sequence('usuarios','userid'), COALESCE((SELECT MAX(userid) FROM usuarios),1));
SELECT setval(pg_get_serial_sequence('detalle_compra','id_detalle_compra'), COALESCE((SELECT MAX(id_detalle_compra) FROM detalle_compra),1));
SELECT setval(pg_get_serial_sequence('detalle_venta','id_detalle_venta'), COALESCE((SELECT MAX(id_detalle_venta) FROM detalle_venta),1));
SELECT setval(pg_get_serial_sequence('abonos','id_abono'), COALESCE((SELECT MAX(id_abono) FROM abonos),1));
SELECT setval(pg_get_serial_sequence('record_crediticio','id_record'), COALESCE((SELECT MAX(id_record) FROM record_crediticio),1));
COMMIT;